#![cfg(feature = "cross-repo-fixtures")]

//! Cross-repo delegation wire-format integration tests.
//!
//! These tests verify that LimeNet's `DelegationContract` can deserialize
//! JSON emitted by the meta-agent Python `delegation_contract_asdict()`
//! exporter, and that the resulting contracts validate or produce the
//! expected structured errors.
//!
//! The JSON fixtures live in `.state/artifacts/delegation_wire/` and are
//! generated by `.state/artifacts/export_delegation_fixtures.py`.
//!
//! ## GAP-DEL-01 resolution
//!
//! Python uses empty strings (`""`) for unset optional identity anchors.
//! LimeNet's custom `deserialize_empty_string_as_none` maps those empty
//! strings to `Option::None` so that contracts with sparse identity anchors
//! validate cleanly on the Rust side.

use limenet::contracts::DelegationContract;
use std::fs;
use std::path::PathBuf;

fn wire_dir() -> PathBuf {
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    manifest_dir
    .parent()
    .unwrap()
        .join(".state")
        .join("artifacts")
        .join("delegation_wire")
}

fn read_wire_fixture(name: &str) -> String {
    let path = wire_dir().join(name);
    fs::read_to_string(&path).unwrap_or_else(|e| panic!("failed to read {path:?}: {e}"))
}

// ---------------------------------------------------------------------------
// Deserialization tests — can LimeNet parse Python-emitted JSON?
// ---------------------------------------------------------------------------

#[test]
fn test_deserialize_all_meta_agent_contracts() {
    let json = read_wire_fixture("all_baseline_contracts.json");
    let contracts: Vec<DelegationContract> =
        serde_json::from_str(&json).expect("all baseline contracts must deserialize");
    assert_eq!(contracts.len(), 6, "expected 6 baseline contracts");
}

#[test]
fn test_deserialize_private_full_strict() {
    let json = read_wire_fixture("private-full-strict.json");
    let c: DelegationContract =
        serde_json::from_str(&json).expect("private-full-strict must deserialize");
    // Empty-string identity anchors from Python are mapped to None
    assert!(c.delegation_id.is_none(), "empty delegation_id must become None");
    assert!(c.upstream_work_request_id.is_none(), "empty upstream_work_request_id must become None");
    assert!(c.upstream_task_id.is_none(), "empty upstream_task_id must become None");
    assert!(c.upstream_backend_id.is_none(), "empty upstream_backend_id must become None");
    assert_eq!(c.downstream_domain_kind, "");
    assert!(c.downstream_graph_id.is_none(), "empty downstream_graph_id must become None");
    // Core policy fields are always present in Python baseline
    assert!(c.visibility_policy.is_some());
    assert!(c.evidence_rollup_policy.is_some());
    assert!(c.status_mapping_policy.is_some());
}

#[test]
fn test_deserialize_full_anchors() {
    let json = read_wire_fixture("full-anchors.json");
    let c: DelegationContract =
        serde_json::from_str(&json).expect("full-anchors must deserialize");
    assert_eq!(c.delegation_id.as_deref(), Some("dg-int2b-003-g-006"));
    assert_eq!(
        c.upstream_work_request_id.as_deref(),
        Some("wr-int2b-003-g-006")
    );
    assert_eq!(c.upstream_task_id.as_deref(), Some("T-int2b-003-g-006"));
    assert_eq!(c.upstream_backend_id.as_deref(), Some("limenet-prod"));
    assert_eq!(c.downstream_domain_kind, "meta-agent");
    assert_eq!(
        c.downstream_graph_id.as_deref(),
        Some("graph-int2b-003-g-006")
    );
}

#[test]
fn test_deserialize_upstream_only() {
    let json = read_wire_fixture("upstream-only.json");
    let c: DelegationContract =
        serde_json::from_str(&json).expect("upstream-only must deserialize");
    assert_eq!(c.upstream_backend_id.as_deref(), Some("limenet-prod"));
    assert_eq!(
        c.upstream_work_request_id.as_deref(),
        Some("wr-int2b-003-g-004")
    );
    // Empty-string downstream fields are mapped to None
    assert!(c.downstream_graph_id.is_none(), "empty downstream_graph_id must become None");
}

#[test]
fn test_deserialize_downstream_only() {
    let json = read_wire_fixture("downstream-only.json");
    let c: DelegationContract =
        serde_json::from_str(&json).expect("downstream-only must deserialize");
    assert_eq!(c.downstream_domain_kind, "meta-agent");
    assert_eq!(
        c.downstream_graph_id.as_deref(),
        Some("graph-int2b-003-g-005")
    );
    // Empty-string upstream fields are mapped to None
    assert!(c.upstream_backend_id.is_none(), "empty upstream_backend_id must become None");
}

