// ---------------------------------------------------------------------------
// Policy-field coverage tests — every policy axis must be present
// ---------------------------------------------------------------------------

#[test]
fn test_all_policy_axes_present_in_baseline() {
    let json = read_wire_fixture("all_baseline_contracts.json");
    let contracts: Vec<DelegationContract> = serde_json::from_str(&json).unwrap();

    let visibilities: Vec<_> = contracts.iter().filter_map(|c| c.visibility_policy).collect();
    let evidence_policies: Vec<_> = contracts.iter().filter_map(|c| c.evidence_rollup_policy).collect();
    let status_policies: Vec<_> = contracts.iter().filter_map(|c| c.status_mapping_policy).collect();

    // Every contract in the baseline has all three policy fields set
    assert_eq!(
        visibilities.len(),
        contracts.len(),
        "every baseline contract must have a visibility_policy"
    );
    assert_eq!(
        evidence_policies.len(),
        contracts.len(),
        "every baseline contract must have an evidence_rollup_policy"
    );
    assert_eq!(
        status_policies.len(),
        contracts.len(),
        "every baseline contract must have a status_mapping_policy"
    );
}

#[test]
fn test_policy_variants_cover_all_combinations() {
    use limenet::contracts::{EvidenceRollupPolicy, StatusMappingPolicy, VisibilityPolicy};

    let json = read_wire_fixture("all_baseline_contracts.json");
    let contracts: Vec<DelegationContract> = serde_json::from_str(&json).unwrap();

    let visibilities: std::collections::HashSet<_> =
        contracts.iter().filter_map(|c| c.visibility_policy).collect();
    let evidence_policies: std::collections::HashSet<_> =
        contracts.iter().filter_map(|c| c.evidence_rollup_policy).collect();
    let status_policies: std::collections::HashSet<_> =
        contracts.iter().filter_map(|c| c.status_mapping_policy).collect();

    assert!(
        visibilities.contains(&VisibilityPolicy::Private),
        "baseline must cover private visibility"
    );
    assert!(
        visibilities.contains(&VisibilityPolicy::Public),
        "baseline must cover public visibility"
    );
    assert!(
        visibilities.contains(&VisibilityPolicy::Shared),
        "baseline must cover shared visibility"
    );

    assert!(
        evidence_policies.contains(&EvidenceRollupPolicy::None),
        "baseline must cover none evidence rollup"
    );
    assert!(
        evidence_policies.contains(&EvidenceRollupPolicy::Summary),
        "baseline must cover summary evidence rollup"
    );
    assert!(
        evidence_policies.contains(&EvidenceRollupPolicy::Full),
        "baseline must cover full evidence rollup"
    );

    assert!(
        status_policies.contains(&StatusMappingPolicy::Strict),
        "baseline must cover strict status mapping"
    );
    assert!(
        status_policies.contains(&StatusMappingPolicy::Loose),
        "baseline must cover loose status mapping"
    );
    assert!(
        status_policies.contains(&StatusMappingPolicy::Passthrough),
        "baseline must cover passthrough status mapping"
    );
}

// ---------------------------------------------------------------------------
// Structured validation error tests (still verify error shape for truly
// invalid contracts)
// ---------------------------------------------------------------------------

#[test]
fn test_structured_error_for_empty_domain_kind_with_graph_id() {
    // Manually construct a contract that has a graph_id but empty domain_kind
    let json = r#"{
        "downstream_domain_kind": "",
        "downstream_graph_id": "g-001"
    }"#;
    let c: DelegationContract = serde_json::from_str(json).unwrap();
    let err = c.validate_structured().unwrap_err();
    assert_eq!(err.error, "validation_failed");
    assert_eq!(err.reason, "empty_field");
    assert_eq!(err.field.as_deref(), Some("downstream_domain_kind"));
    assert_eq!(err.anchor.as_deref(), Some("downstream"));
}

